package run.ikaros.finance; import jakarta.validation.Valid; import java.util.UUID; import org.springframework.web.bind.annotation.*; import reactor.core.publisher.Flux; import reactor.core.publisher.Mono; @RestController @RequestMapping("/api/v2/finance") public class FinanceController{private final FinanceService service;public FinanceController(FinanceService s){service=s;}@PostMapping("/ledgers")public Mono<LedgerView> ledger(@RequestHeader("X-Ikaros-Actor-Id")UUID a,@Valid@RequestBody CreateLedgerRequest r){return service.createLedger(a,r);}@GetMapping("/ledgers")public Flux<LedgerView> ledgers(@RequestHeader("X-Ikaros-Actor-Id")UUID a){return service.listLedgers(a);}@PostMapping("/ledgers/{ledgerId}/accounts")public Mono<AccountView> account(@RequestHeader("X-Ikaros-Actor-Id")UUID a,@PathVariable UUID ledgerId,@Valid@RequestBody CreateAccountRequest r){return service.createAccount(a,ledgerId,r);}@GetMapping("/ledgers/{ledgerId}/accounts")public Flux<AccountView> accounts(@RequestHeader("X-Ikaros-Actor-Id")UUID a,@PathVariable UUID ledgerId){return service.listAccounts(a,ledgerId);}}
